{
  "name": "@chncaesar/opencode-portable",
  "version": "0.1.1",
  "description": "Move OpenCode config, MCP servers and user state between machines",
  "author": "Jiachuan Zhu",
  "keywords": [
    "opencode",
    "migration",
    "backup",
    "mcp",
    "sessions"
  ],
  "homepage": "https://github.com/chncaesar/opencode-portable#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/chncaesar/opencode-portable.git"
  },
  "bugs": {
    "url": "https://github.com/chncaesar/opencode-portable/issues"
  },
  "type": "module",
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "bin": {
    "opencode-portable": "dist/cli.js"
  },
  "files": [
    "dist",
    "README.md",
    "README.zh-CN.md",
    "assets",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "test": "vitest run",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build && npm test"
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1",
    "tar": "^7.5.22"
  },
  "devDependencies": {
    "@types/node": "^26.6.6",
    "typescript": "^7.0.2",
    "vitest": "^5.1.0"
  }
}
